/// G2 (superellipse-compensated) corner radii.
pub mod radius {
    pub const CONTROL: f64 = 7.09873886520133;
    pub const MENU: f64 = 11.357982184322127;
    pub const PANEL: f64 = 17.03697327648319;
    /// Concentric nesting: inner = outer - padding, never below 4.
    pub fn inner(outer: f64, padding: f64) -> f64 { (outer - padding).max(4.0) }
}

